const http = require('http');
const { URL } = require('url');

function createExpress() {
  const middlewares = [];
  const routes = [];

  const app = function (req, res) {
    enhanceResponse(res);

    const requestUrl = new URL(req.url, `${req.protocol || 'http'}://${req.headers.host}`);
    req.path = requestUrl.pathname;
    req.query = Object.fromEntries(requestUrl.searchParams.entries());
    req.params = {};

    const stack = middlewares.slice();
    const method = req.method.toUpperCase();
    const route = findRoute(routes, method, req.path, req.params);
    if (route) {
      stack.push(route.handler);
    }

    let idx = 0;
    const next = (err) => {
      if (res.writableEnded) {
        return;
      }
      const layer = stack[idx++];
      if (!layer) {
        if (err) {
          const status = err.statusCode || err.status || 500;
          res.status(status).json({ error: err.message || 'Internal Server Error' });
          return;
        }
        res.status(404).json({ error: 'Not Found' });
        return;
      }

      try {
        if (err) {
          if (layer.length === 4) {
            const possiblePromise = layer(err, req, res, next);
            if (isPromise(possiblePromise)) {
              possiblePromise.catch(next);
            }
          } else {
            next(err);
          }
          return;
        }

        if (layer.length === 4) {
          next();
          return;
        }

        const possiblePromise = layer(req, res, next);
        if (isPromise(possiblePromise)) {
          possiblePromise.catch(next);
        }
      } catch (error) {
        next(error);
      }
    };

    next();
  };

  app.use = function (middleware) {
    middlewares.push(middleware);
  };

  ['get', 'post', 'put', 'delete', 'patch', 'options'].forEach((method) => {
    app[method] = (path, handler) => {
      routes.push({ method: method.toUpperCase(), path, handler });
      return app;
    };
  });

  app.listen = function (port, callback) {
    const server = http.createServer((req, res) => {
      req.protocol = 'http';
      app(req, res);
    });
    return server.listen(port, callback);
  };

  return app;
}

function findRoute(routes, method, path, params) {
  for (const route of routes) {
    if (route.method !== method) continue;
    const match = matchPath(route.path, path);
    if (match) {
      Object.assign(params, match);
      return route;
    }
  }
  return null;
}

function matchPath(routePath, actualPath) {
  if (routePath === actualPath) {
    return {};
  }
  const routeParts = routePath.split('/').filter(Boolean);
  const actualParts = actualPath.split('/').filter(Boolean);
  if (routeParts.length !== actualParts.length) {
    return null;
  }
  const params = {};
  for (let i = 0; i < routeParts.length; i += 1) {
    const routePart = routeParts[i];
    const actualPart = actualParts[i];
    if (routePart.startsWith(':')) {
      params[routePart.slice(1)] = decodeURIComponent(actualPart);
    } else if (routePart !== actualPart) {
      return null;
    }
  }
  return params;
}

function enhanceResponse(res) {
  if (res._enhanced) return;
  res._enhanced = true;
  res.status = function (statusCode) {
    res.statusCode = statusCode;
    return res;
  };
  res.json = function (payload) {
    if (!res.getHeader('Content-Type')) {
      res.setHeader('Content-Type', 'application/json');
    }
    res.end(JSON.stringify(payload));
  };
  res.send = function (payload) {
    if (typeof payload === 'object') {
      return res.json(payload);
    }
    res.end(payload);
  };
}

function isPromise(value) {
  return value && typeof value.then === 'function';
}

createExpress.json = function () {
  return function (req, res, next) {
    if (req.body !== undefined) {
      next();
      return;
    }
    const method = req.method.toUpperCase();
    if (method === 'GET' || method === 'HEAD') {
      req.body = {};
      next();
      return;
    }
    const contentType = req.headers['content-type'] || '';
    if (!contentType.includes('application/json')) {
      req.body = {};
      next();
      return;
    }

    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
    });
    req.on('end', () => {
      if (!raw) {
        req.body = {};
        next();
        return;
      }
      try {
        req.body = JSON.parse(raw);
        next();
      } catch (error) {
        res.status(400).json({ error: 'Invalid JSON payload' });
      }
    });
    req.on('error', () => {
      res.status(400).json({ error: 'Error reading request body' });
    });
  };
};

module.exports = createExpress;
